/**
 * The vendor SVG for a folder. Unknown names fall back to the plain folder, so a tree of
 * unrecognised directories still reads as directories.
 */
export function getRawFolderIconSvg(folderName: string, expanded: boolean): string {
  const iconName = FOLDER_NAME_TO_ICON[folderName.toLowerCase()] ?? "folder";
  const key = expanded ? `${iconName}-open` : iconName;
  return FOLDER_SVG_ICONS[key] ?? FOLDER_SVG_ICONS[expanded ? "folder-open" : "folder"];
}
